TRADING_DAYS_PER_YEAR = 250

def turnover_from_holding_period(holding_days):
    return TRADING_DAYS_PER_YEAR / holding_days

def cost_drag_from_holding_period(holding_days, round_trip_cost_pct):
    return turnover_from_holding_period(holding_days) * round_trip_cost_pct

def min_holding_period(round_trip_cost_pct, max_drag_pct):
    return TRADING_DAYS_PER_YEAR * round_trip_cost_pct / max_drag_pct

print(round(cost_drag_from_holding_period(20, 0.30), 2))   # 3.75
print(round(min_holding_period(0.30, 2.0), 2))              # 37.5
